 s=json.loads((R/'summary.json').read_text());v=json.loads((R/'validation.json').read_text());assert v['passed'];cov=s['coverage'];prep=s['preparation'];m=pd.read_csv(P/'flow_metrics.csv');df=pd.read_csv(P/'passage_comparison.csv');dev='development_previously_inspected20';cal='development_original_calibration65'
